	/**
	 * Default Constructor
	 */
    public MeasureService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new MeasureEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(MeasureRepository.class) );
		this.validator		= applicationContext.getBean(MeasureValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Measure
	 */
		public Measure createMeasure( CreateMeasureCommand command ) {

		Measure entity = new Measure();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setMeasureId( command.getMeasureId() );
            entity.setName( command.getName() );
            entity.setFormat( command.getFormat() );
            entity.setAggregation( command.getAggregation() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Measure {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateMeasureCommand
	 * @return		Measure
	 */
	public Measure updateMeasure( UpdateMeasureCommand command ) {

		Measure entity = new Measure();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setMeasureId( command.getMeasureId() );
            entity.setName( command.getName() );
            entity.setFormat( command.getFormat() );
            entity.setSemanticModel( command.getSemanticModel() );
            entity.setDatasets( command.getDatasets() );
            entity.setGlossaryTerms( command.getGlossaryTerms() );
            entity.setAggregation( command.getAggregation() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Measure {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteMeasureCommand
	 */
	public void delete( DeleteMeasureCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getMeasureId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Measure {0} ", id );

	}

	/**
	 * Method to retrieve the Measure via MeasureFetchOneSummary
	 * @param 	summary MeasureFetchOneSummary
	 * @return 	MeasureFetchOneResponse
	 */
	public Measure getMeasure( MeasureFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "MeasureFetchOneSummary arg cannot be null" );

		Measure entity = null;
		UUID id = summary.getMeasureId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Measure using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Measures
	 *
	 * @return 	List<Measure>
	 */
    public List<Measure> getAllMeasure() {
		List<Measure> list = projector.findAll( new FindAllMeasureQuery() );
		return list;
	}

	/**
	 * assign SemanticModel on Measure
	 * @param		command AssignSemanticModelToMeasureCommand
	 */
	public void assignSemanticModel( AssignSemanticModelToMeasureCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignSemanticModel(command.getMeasureId(), command.getAssignment());

	}

	/**
	 * unAssign SemanticModel on Measure
	 * @param		command UnAssignSemanticModelFromMeasureCommand
	 */
	public void unAssignSemanticModel( UnAssignSemanticModelFromMeasureCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignSemanticModel(command.getMeasureId());
	}
	

